Stackoverflow question:
 Practicality of the position attribute of a Positional List Implementation in Python?<p>I am reading Chapter 7 of <a href="https://rads.stackoverflow.com/amzn/click/com/1118290275" rel="nofollow noreferrer" rel="nofollow noreferrer">Data Structures and Algorithms in Python</a> and I am finding the Positional List ADT quite hard to understand, the implementation given by the book looks like this:</p>
<pre><code>class _DoublyLinkedBase:
    &quot;&quot;&quot; A base class providing a doubly linked list representation.&quot;&quot;&quot;
    class _Node:
        __slots__ = '_element' , '_prev' , '_next' # streamline memory
        def __init__(self, element, prev, next): # initialize node’s fields
            self._element = element # user’s element
            self._prev = prev # previous node reference
            self._next = next # next node reference

    # MAIN METHODS
    def __init__(self):
        self._header = self._Node(None, None, None)
        self._trailer = self._Node(None, None, None)
        self._header._next = self._trailer # trailer is after header
        self._trailer._prev = self._header # header is before trailer
        self._size = 0 # number of elements

    def __len__(self):
        return self._size

    def is_empty(self):
        return self._size == 0

    def _insert_between(self, e, predecessor, successor):
        newest = self._Node(e, predecessor, successor) # linked to neighbors
        predecessor._next = newest
        successor._prev = newest
        self._size += 1

        return newest

    def _delete_node(self, node):
        predecessor = node._prev
        successor = node._next
        predecessor._next = successor
        successor._prev = predecessor
        self._size -= 1
        element = node._element # record deleted element
        node._prev = node._next = node._element = None # deprecate node
        return element # return deleted element


class PositionalList(_DoublyLinkedBase):
    &quot;&quot;&quot; A sequential container of elements allowing positional access.&quot;&quot;&quot;
    #-------------------------- nested Position class --------------------------
    class Position:
        &quot;&quot;&quot; An abstraction representing the location of a single element.&quot;&quot;&quot;
        def __init__(self, container, node):
            &quot;&quot;&quot; Constructor should not be invoked by user.&quot;&quot;&quot;
            self._container = container
            self._node = node

        def element(self):
            &quot;&quot;&quot; Return the element stored at this Position.&quot;&quot;&quot;
            return self._node._element

        def __eq__(self, other):
            &quot;&quot;&quot; Return True if other is a Position representing the same location.&quot;&quot;&quot;
            return type(other) is type(self) and other._node is self._node

        def __ne__(self, other):
            &quot;&quot;&quot; Return True if other does not represent the same location.&quot;&quot;&quot;
            return not (self == other) # opposite of eq
    #-------------------------- End of nested Position class --------------------
    #------------------------------- utility method -------------------------------
    def _validate(self, p):
        &quot;&quot;&quot; Return position s node, or raise appropriate error if invalid.&quot;&quot;&quot;
        if not isinstance(p, self.Position):
            raise TypeError(&quot;p must be proper Position type&quot;)
        if p._container is not self:
            raise ValueError(&quot;p does not belong to this container&quot;)
        if p._node._next is None: # convention for deprecated nodes
            raise ValueError(&quot;p is no longer valid&quot;)
        return p._node

    #------------------------------- utility method -------------------------------
    def _make_position(self, node):
        &quot;&quot;&quot; Return Position instance for given node (or None if sentinel).&quot;&quot;&quot;
        if node is self._header or node is self._trailer:
            return None # boundary violation
        else:
            return self.Position(self, node) # legitimate position

    #------------------------------- accessors -------------------------------
    def first(self):
        &quot;&quot;&quot; Return the first Position in the list (or None if list is empty).&quot;&quot;&quot;
        return self._make_position(self._header._next)

    def last(self):
        &quot;&quot;&quot; Return the last Position in the list (or None if list is empty).&quot;&quot;&quot;
        return self._make_position(self._trailer._prev)

    def before(self, p):
        &quot;&quot;&quot; Return the Position just before Position p (or None if p is first).&quot;&quot;&quot;
        node = self._validate(p)
        return self._make_position(node._prev)

    def after(self, p):
        &quot;&quot;&quot; Return the Position just after Position p (or None if p is last).&quot;&quot;&quot;
        node = self._validate(p)
        return self._make_position(node._next)

    def __iter__(self):
        &quot;&quot;&quot; Generate a forward iteration of the elements of the list.&quot;&quot;&quot;
        cursor = self.first( )
        while cursor is not None:
            yield cursor.element( )
            cursor = self.after(cursor)

    #------------------------------- mutators -------------------------------
    # override inherited version to return Position, rather than Node
    def _insert_between(self, e, predecessor, successor):
        &quot;&quot;&quot; Add element between existing nodes and return new Position.&quot;&quot;&quot;
        node = super()._insert_between(e, predecessor, successor)
        return self._make_position(node)

    def add_first(self, e):
        &quot;&quot;&quot;&quot; Insert element e at the front of the list and return new Position.&quot;&quot;&quot;
        return self._insert_between(e, self._header, self._header._next)

    def add_last(self, e):
        &quot;&quot;&quot; Insert element e at the back of the list and return new Position.&quot;&quot;&quot;
        return self._insert_between(e, self._trailer._prev, self._trailer)

    def add_before(self, p, e):
        &quot;&quot;&quot; Insert element e into list before Position p and return new Position.&quot;&quot;&quot;
        original = self._validate(p)
        return self._insert_between(e, original._prev, original)

    def add_after(self, p, e):
        &quot;&quot;&quot; Insert element e into list after Position p and return new Position.&quot;&quot;&quot;
        original = self._validate(p)
        return self._insert_between(e, original, original._next)

    def delete(self, p):
